SELECT





                    ST_ASTEXT(
                    ST_transform(
                    ST_INTERSECTION(
                    ST_BUFFER(${column},-0.00),st_geomfromtext('POLYGON((-180 85,180 85,180 -85,-180 -85,-180 85))',4326)
                    ),${srsName})
                    ) AS ${column}


                    ST_ASTEXT(ST_transform(${column},${srsName})) AS ${column}




            "${column}"



FROM "${tableName}" WHERE 1 = 1

    AND ${primaryKey} NOT IN ( SELECT "${primaryKey}" FROM "${tableName}" WHERE st_y(${geom}) NOT BETWEEN -85 AND 85 )

SELECT





                    ST_ASTEXT(
                    ST_transform(
                    ST_INTERSECTION(
                    ST_BUFFER(${column},-0.00),st_geomfromtext('POLYGON((-180 85,180 85,180 -85,-180 -85,-180 85))',4326)
                    ),${srsName})
                    ) AS ${column}


                    ST_ASTEXT(ST_transform(ST_SETSRID(${column},4326),${srsName})) AS ${column}




            "${column}"



FROM "${tableName}" WHERE 1 = 1

    AND ${primaryKey} NOT IN ( SELECT "${primaryKey}" FROM "${tableName}" WHERE st_y(${geom}) NOT BETWEEN -85 AND 85 )

